    public int romanToInt(String s) {
        int total = 0;
        int previous = 0;
        for (int i = 0; i < s.length(); i++) {
            int current = valueOf(s.charAt(i));
            total += current;
            if (previous < current) {
                total -= 2 * previous;
            }
            previous = current;
        }
        return total;
    }

